package sn.groupia.media.domain.service;

import java.util.Optional;
import sn.groupia.media.domain.model.MediaRendition;

/** All operations run outside database transactions. Keys are generated by Media only. */
public interface MediaObjectStorage {
    void put(MediaRendition rendition, byte[] bytes);

    Optional<StoredObject> head(String key);

    void delete(String key);

    String resolveUrl(String key);

    record StoredObject(long sizeBytes, String sha256) {}
}
